class AdminErrorBoundary extends Component<{ children: React.ReactNode }, { error: Error | null }> {
  state = { error: null as Error | null };
  static getDerivedStateFromError(error: Error) { return { error }; }
  componentDidCatch(error: Error, info: ErrorInfo) { console.error('Admin runtime error', error, info.componentStack); }
  render() { if (this.state.error) return <div className="admin-error-screen"><h1>Admin gặp lỗi khi hiển thị</h1><p>Đã xảy ra lỗi khi xử lý thao tác này. Vui lòng thử lại hoặc liên hệ kỹ thuật.</p><button onClick={() => window.location.reload()}>Tải lại Admin</button><a href="#/">Về website</a></div>; return this.props.children; }
}
