function ProductCatalogPage({ products, query, setQuery, category, setCategory, categorySlug }: { products: Product[]; query: string; setQuery: (value: string) => void; category: string; setCategory: (value: string) => void; categorySlug?: string }) { const names: Record<string, string> = { 'may-cat-kts': 'Máy cắt KTS', 'luoi-dao': 'Lưỡi dao', 'tham-ni': 'Thảm nỉ', 'dau-dao-may-cat-kts': 'Đầu dao máy cắt KTS' }; const selectedCategory = categorySlug ? names[categorySlug] || 'Danh mục sản phẩm' : 'Tất cả sản phẩm'; const activeCategory = names[categorySlug || ''] || category; const visible = products.filter(product => (activeCategory === 'Tất cả' || activeCategory === 'Tất cả sản phẩm' || product.category === activeCategory) && product.name.toLowerCase().includes(query.toLowerCase())); const count = (name: string) => products.filter(product => product.category === name).length; return <main><section className="catalog-hero"><div className="container"><div className="breadcrumb"><a href="#/">Trang chủ</a><span>/</span><span>Sản phẩm</span>{categorySlug && <><span>/</span><b>{selectedCategory}</b></>}</div><span className="eyebrow light">DANH MỤC SẢN PHẨM</span><h1>{selectedCategory}</h1><p>{categorySlug ? `Các sản phẩm thuộc nhóm ${selectedCategory.toLowerCase()}, được chọn lọc cho quy trình sản xuất chính xác.` : 'Khám phá hệ sinh thái máy cắt kỹ thuật số, lưỡi dao và phụ kiện chuyên dụng của Chính Thực.'}</p></div></section><section className="catalog catalog-page container"><div className="catalog-toolbar"><div><b>{visible.length}</b> sản phẩm</div><label className="catalog-search"><Search size={16}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Tìm trong danh mục"/></label></div><div className="catalog-layout"><aside className="catalog-sidebar"><b>Danh mục</b>{categories.slice(1).map(item => <button className={(activeCategory === item ? 'active' : '')} onClick={() => { setCategory(item); window.location.hash = `#/danh-muc/${item === 'Máy cắt KTS' ? 'may-cat-kts' : item === 'Lưỡi dao' ? 'luoi-dao' : item === 'Thảm nỉ' ? 'tham-ni' : 'dau-dao-may-cat-kts'}`; }} key={item}>{item} <small>({count(item)})</small></button>)}<button className={!categorySlug && category === 'Tất cả' ? 'active' : ''} onClick={() => { setCategory('Tất cả'); window.location.hash = '#/san-pham'; }}>Tất cả sản phẩm <small>({products.length})</small></button></aside><div className="catalog-results"><div className="grid">{visible.map(product => <ProductCard p={product} key={product.id}/>)}</div>{visible.length === 0 && <div className="empty-state">Không tìm thấy sản phẩm phù hợp.</div>}</div></div></section></main>; }
