function HomePage({ products, settings = {}, sliders = [] }: { products: Product[]; settings?: Record<string,string>; sliders?: any[] }) { const [slideIndex, setSlideIndex] = useState(0); const [slideFailed, setSlideFailed] = useState(false); useEffect(() => { setSlideIndex(0); setSlideFailed(false); }, [sliders.length]); useEffect(() => { if (sliders.length < 2) return; const timer = window.setInterval(() => { setSlideIndex(index => (index + 1) % sliders.length); setSlideFailed(false); }, 5000); return () => window.clearInterval(timer); }, [sliders.length]); const featured = products.filter(product => product.featured || product.bestseller).slice(0, 4); const featuredProducts = featured.length ? featured : products.slice(0, 4); const quickCategories = [['may-cat-kts', 'Máy cắt KTS'], ['luoi-dao', 'Lưỡi dao'], ['tham-ni', 'Thảm nỉ'], ['dau-dao-may-cat-kts', 'Đầu dao máy cắt KTS']]; return <><main><section className={`hero ${slideFailed ? 'hero-slide-failed' : ''}`}><div className="hero-backgrounds" aria-hidden="true">{sliders.map((slider, index) => <img className={index === slideIndex && !slideFailed ? 'active' : ''} src={slider.image} alt="" onError={() => index === slideIndex && setSlideFailed(true)} key={slider.id}/>)}</div><div className="hero-overlay" aria-hidden="true"/><div className="hero-content"><span className="eyebrow light">ĐỐI TÁC KỸ THUẬT CỦA BẠN</span><h1>Giải pháp cắt<br/><i>chính xác.</i> Sản xuất<br/>hiệu quả hơn.</h1><p>Máy cắt kỹ thuật số, lưỡi dao và phụ kiện chuyên dụng cho doanh nghiệp Việt.</p><a className="btn yellow" href="#/san-pham">Khám phá sản phẩm <ArrowRight size={17}/></a></div><div className="hero-image"><img src="https://chinhthucmayktscnc.com/wp-content/uploads/2025/09/banner-1-1400x609.png" alt="Máy cắt kỹ thuật số Chính Thực"/></div>{sliders.length > 1 && <div className="hero-dots" aria-label="Điều hướng slider">{sliders.map((slider, index) => <button type="button" className={index === slideIndex ? 'active' : ''} aria-label={`Chuyển tới slide ${index + 1}`} onClick={() => { setSlideIndex(index); setSlideFailed(false); }} key={slider.id}/>)}</div>}</section>{false && <section className="hero-slider" aria-label="Slider trang chủ">{sliders.map(slider => <a href={slider.link || '#/san-pham'} key={slider.id}><img src={slider.image} alt={slider.title || 'Slider Chính Thực'}/>{slider.title && <span>{slider.title}</span>}</a>)}</section>}<section className="trust"><div><Zap size={22}/><span><b>12+ năm</b><small>Kinh nghiệm ngành máy</small></span></div><div><span className="trustnum">500+</span><span><b>Dự án triển khai</b><small>Đồng hành cùng doanh nghiệp</small></span></div><div><span className="trustnum">100%</span><span><b>Chính hãng</b><small>Sản phẩm nguồn gốc rõ ràng</small></span></div></section><section className="home-section container"><div className="section-head"><div><span className="eyebrow">SẢN PHẨM NỔI BẬT</span><h2>Thiết bị cho mọi<br/><i>đường cắt.</i></h2></div><a className="textlink" href="#/san-pham">Xem toàn bộ sản phẩm <ArrowRight size={16}/></a></div><div className="grid">{featuredProducts.map(product => <ProductCard p={product} key={product.id}/>)}</div></section><section className="home-section category-section container"><div className="section-head"><div><span className="eyebrow">KHÁM PHÁ THEO NHÓM</span><h2>Chọn đúng nhóm<br/><i>cho công việc.</i></h2></div></div><div className="quick-category-grid">{quickCategories.map(([slug, label]) => <a href={`#/danh-muc/${slug}`} key={slug}><span>{label}</span><ArrowRight size={18}/></a>)}</div></section><section className="cta"><div><span className="eyebrow light">CHƯA BIẾT CHỌN GÌ?</span><h2>Hãy để chúng tôi<br/><i>tư vấn giải pháp.</i></h2></div><a className="btn yellow" href="#/lien-he">Trao đổi với chuyên gia <ArrowRight size={17}/></a></section></main></>; }
function ProductDetailPage({ product, onAdd }: { product: Product & { sku?: string; brand?: string; gallery?: string | string[]; specs?: string | Array<{ model?: string; values?: Record<string, string> }>; video_url?: string; documents?: string | Array<{ name: string; url: string }>; badges?: string | string[] }; onAdd: (id: string) => void }) { useEffect(() => { window.scrollTo({ top: 0, left: 0, behavior: 'auto' }); }, [product.slug]); const gallery = [product.image, ...(Array.isArray(product.gallery) ? product.gallery : (() => { try { return JSON.parse(product.gallery || '[]'); } catch { return []; } })())].filter(Boolean); const [activeImage, setActiveImage] = useState(gallery[0]); const [lightbox, setLightbox] = useState(false); const [lightboxIndex, setLightboxIndex] = useState(0); const showImage = (index: number) => { setActiveImage(gallery[index]); setLightboxIndex(index); }; useEffect(() => { const onKey = (event: KeyboardEvent) => { if (!lightbox) return; if (event.key === 'Escape') setLightbox(false); if (event.key === 'ArrowRight') showImage((lightboxIndex + 1) % gallery.length); if (event.key === 'ArrowLeft') showImage((lightboxIndex - 1 + gallery.length) % gallery.length); }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); }, [lightbox, lightboxIndex, gallery.length]); const specs = Array.isArray(product.specs) ? product.specs : (() => { try { return JSON.parse(product.specs || '[]'); } catch { return []; } })(); const documents = Array.isArray(product.documents) ? product.documents : (() => { try { return JSON.parse(product.documents || '[]'); } catch { return []; } })(); const badges = Array.isArray(product.badges) ? product.badges : (() => { try { return JSON.parse(product.badges || '[]'); } catch { return []; } })(); const highlights = Array.isArray(product.highlights) ? product.highlights : (() => { try { return JSON.parse(product.highlights || '[]'); } catch { return []; } })(); const applications = Array.isArray(product.applications) ? product.applications : (() => { try { return JSON.parse(product.applications || '[]'); } catch { return []; } })(); return <main><section className="detail container"><div><div className="detail-image" onClick={() => { setLightboxIndex(gallery.indexOf(activeImage)); setLightbox(true); }}><SafeImage src={activeImage} alt={product.name}/><span className="zoom-hint">Phóng to ảnh</span></div>{gallery.length > 1 && <div className="detail-thumbs">{gallery.map((image, index) => <button className={activeImage === image ? 'active' : ''} onClick={() => showImage(index)} key={`${image}-${index}`}><SafeImage src={image} alt={`${product.name} ảnh ${index + 1}`}/></button>)}</div>}</div><div className="detail-copy"><div className="breadcrumb dark"><a href="#/">Trang chủ</a><span>/</span><a href="#/san-pham">Sản phẩm</a><span>/</span><b>{product.category}</b></div><div className="badge-row">{badges.map((badge: string) => <span key={badge}>{badge}</span>)}</div><span className="eyebrow">{product.category}</span><h1>{product.name}</h1>{(product.brand || product.sku) && <div className="product-meta">{product.brand && <span>Thương hiệu: <b>{product.brand}</b></span>}{product.sku && <span>Mã sản phẩm: <b>{product.sku}</b></span>}</div>}<p className="price">Giá liên hệ</p><p>{product.description}</p><div className="detail-actions"><button className="btn primary" onClick={() => onAdd(product.id)}>Thêm vào yêu cầu báo giá <ArrowRight size={17}/></button><a className="quick-call" href="tel:0916412896">Gọi tư vấn</a><a className="quick-zalo" href="https://zalo.me/0916412896">Zalo</a></div><form className="quick-quote" onSubmit={event => { event.preventDefault(); }}><h3>Nhận tư vấn sản phẩm này</h3><label>Họ tên<input name="name" required placeholder="Họ tên" autoComplete="name"/></label><label>Số điện thoại<input name="phone" required type="tel" placeholder="Số điện thoại" autoComplete="tel"/></label><label>Email<input name="email" required type="email" placeholder="Email" autoComplete="email"/></label><label>Nội dung cần tư vấn<textarea name="message" required placeholder={`Nội dung cần tư vấn về ${product.name}`}/></label><button className="btn primary" type="submit">Gửi yêu cầu báo giá</button></form></div></section>{highlights.length > 0 && <section className="detail-extra container"><h2>Đặc điểm nổi bật</h2><ul className="highlight-list">{highlights.map((item: string) => <li key={item}>✓ <span>{item}</span></li>)}</ul></section>}{applications.length > 0 && <section className="detail-extra container"><h2>Ứng dụng theo ngành</h2><div className="application-grid">{applications.map((item: { industry: string; description: string }) => <article key={item.industry}><h3>{item.industry}</h3><p>{item.description}</p></article>)}</div></section>}{specs.length > 0 && <section className="detail-extra container"><h2>Thông số kỹ thuật</h2><div className="spec-table">{specs.map((spec: { model?: string; values?: Record<string, string> }, index: number) => <div className="spec-model" key={spec.model || index}>{specs.length > 1 && <h3>{spec.model || `Model ${index + 1}`}</h3>}{Object.entries(spec.values || spec).filter(([key]) => key !== 'model' && key !== 'values').map(([key, value]) => <div key={key}><span>{key}</span><b>{String(value)}</b></div>)}</div>)}</div></section>}{product.video_url && <section className="detail-extra container"><h2>Video giới thiệu</h2><div className="video-frame"><iframe src={product.video_url.replace('watch?v=', 'embed/')} title={`Video ${product.name}`} allowFullScreen/></div></section>}{documents.length > 0 && <section className="detail-extra container"><h2>Tài liệu sản phẩm</h2><div className="document-list">{documents.map((doc: { name: string; url: string }) => <a href={doc.url} target="_blank" rel="noreferrer" key={doc.url}>{doc.name} <ArrowRight size={15}/></a>)}</div></section>}{lightbox && <div className="lightbox" role="dialog" aria-label="Xem ảnh sản phẩm" onClick={() => setLightbox(false)}><div className="lightbox-content" onClick={event => event.stopPropagation()}><button className="lightbox-prev" onClick={() => showImage((lightboxIndex - 1 + gallery.length) % gallery.length)} aria-label="Ảnh trước">‹</button><SafeImage src={gallery[lightboxIndex]} alt={`${product.name} ảnh lớn ${lightboxIndex + 1}`}/><button className="lightbox-next" onClick={() => showImage((lightboxIndex + 1) % gallery.length)} aria-label="Ảnh tiếp theo">›</button><button className="lightbox-close" onClick={() => setLightbox(false)} aria-label="Đóng">Đóng</button></div></div>}</main>; }
function CmsPublicPage({ slug, fallbackTitle, fallbackKicker }: { slug: string; fallbackTitle: string; fallbackKicker: string }) { const [page, setPage] = useState<any>(null); useEffect(() => { api(`/pages/${slug}`).then(data => setPage(data.page)).catch(() => undefined); }, [slug]); return <ContentPage title={page?.title || fallbackTitle} kicker={fallbackKicker}><div className="cms-public-content" dangerouslySetInnerHTML={{ __html: page?.content || '<p>Nội dung đang được cập nhật.</p>' }}/></ContentPage>; }
