function ContactPage({ settings }: { settings: Record<string,string> }) { const [status, setStatus] = useState(''); const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); try { await api('/quotes', { method: 'POST', body: JSON.stringify({ name: data.get('name'), email: data.get('email'), message: data.get('message') }) }); setStatus('Đã gửi yêu cầu. Chúng tôi sẽ liên hệ sớm.'); event.currentTarget.reset(); } catch (error) { setStatus((error as Error).message); } }; return <ContentPage title="Trao đổi với chuyên gia" kicker="LIÊN HỆ"><div className="contact-grid"><div><h2>Chúng tôi sẵn sàng tư vấn.</h2><p>Hotline: <b>{settings.hotline || '0916 412 896'}</b></p><p>Email: {settings.email || 'chinhthucmaycnc@gmail.com'}</p><p>{settings.address || 'Bình Dương, Việt Nam'}</p></div><form className="quick-quote" onSubmit={submit}><label>Họ tên<input name="name" required /></label><label>Email<input name="email" type="email" required /></label><label>Nội dung<textarea name="message" required /></label><button className="btn primary" type="submit">Gửi yêu cầu</button>{status && <p className="quick-quote-status success" role="status">{status}</p>}</form></div></ContentPage>; }
