function ProjectDetailPage({ slug }: { slug: string }) { const [project, setProject] = useState<any>(null); useEffect(() => { api(`/projects/${slug}`).then(data => setProject(data.project)).catch(() => undefined); }, [slug]); return <ContentPage title={project?.title || 'Dự án'} kicker={project?.industry || 'DỰ ÁN'}>{project ? <><img className="project-cover" src={project.cover_image} alt={project.title}/><p>{project.summary}</p><section className="project-block"><h2>Thách thức</h2><div dangerouslySetInnerHTML={{ __html: project.challenge }}/></section><section className="project-block"><h2>Giải pháp</h2><div dangerouslySetInnerHTML={{ __html: project.solution }}/></section><section className="project-block"><h2>Kết quả</h2><div dangerouslySetInnerHTML={{ __html: project.result }}/></section></> : <div className="empty-state">Không tìm thấy dự án.</div>}</ContentPage>; }
function NewsDetailPage({ slug }: { slug: string }) { const [post, setPost] = useState<any>(null); useEffect(() => { api(`/posts/${slug}`).then(data => setPost(data.post)).catch(() => undefined); }, [slug]); return <ContentPage title={post?.title || 'Bài viết'} kicker="TIN TỨC"><p>{post?.excerpt}</p><div className="cms-public-content" dangerouslySetInnerHTML={{ __html: post?.content || '<p>Không tìm thấy bài viết.</p>' }}/></ContentPage>; }
function AuthPage({ onLogin, adminOnly = false }: { onLogin: (user: User) => void; adminOnly?: boolean }) { const [register, setRegister] = useState(false); const [error, setError] = useState(''); const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); setError(''); const form = new FormData(event.currentTarget); try { const endpoint = !adminOnly && register ? '/auth/register' : '/auth/login'; const data = await api(endpoint, { method: 'POST', body: JSON.stringify({ name: form.get('name'), email: form.get('email'), password: form.get('password') }) }); if (adminOnly && data.user.role !== 'admin') throw new Error('Tài khoản không có quyền quản trị.'); onLogin(data.user); window.location.hash = adminOnly ? '#/admin?tab=dashboard' : '#/'; } catch (e) { setError((e as Error).message); } }; return <ContentPage title={adminOnly ? 'Đăng nhập quản trị' : register ? 'Tạo tài khoản khách hàng' : 'Đăng nhập tài khoản'} kicker={adminOnly ? 'KHU VỰC QUẢN TRỊ' : 'TÀI KHOẢN'}><form className="auth-form" onSubmit={submit}>{!adminOnly && register && <label>Họ tên<input name="name" required /></label>}<label>Email<input name="email" type="email" required /></label><label>Mật khẩu<input name="password" type="password" minLength={8} required /></label>{error && <p className="form-error">{error}</p>}<button className="btn primary">{register && !adminOnly ? 'Đăng ký' : 'Đăng nhập'} <ArrowRight size={17}/></button>{!adminOnly && <button type="button" className="form-switch" onClick={() => setRegister(!register)}>{register ? 'Đã có tài khoản? Đăng nhập' : 'Chưa có tài khoản? Đăng ký'}</button>}</form></ContentPage>; }
function AdminPage() { const [quotes, setQuotes] = useState<Array<{ id: number; name: string; email: string; message: string; status: string }>>([]); const [error, setError] = useState(''); useEffect(() => { api('/admin/quotes').then(data => setQuotes(data.quotes)).catch(e => setError((e as Error).message)); }, []); return <ContentPage title="Quản trị hệ thống" kicker="ADMIN"><div className="admin-panel"><h2>Yêu cầu báo giá</h2>{error ? <p className="form-error">{error}</p> : quotes.length === 0 ? <div className="empty-state">Chưa có yêu cầu mới.</div> : quotes.map(quote => <div className="admin-row" key={quote.id}><div><b>{quote.name}</b><span>{quote.email}</span><p>{quote.message}</p></div><select value={quote.status} onChange={async e => { await api(`/admin/quotes/${quote.id}`, { method: 'PATCH', body: JSON.stringify({ status: e.target.value }) }); setQuotes(rows => rows.map(row => row.id === quote.id ? { ...row, status: e.target.value } : row)); }}><option value="new">Mới</option><option value="contacted">Đã liên hệ</option><option value="closed">Đã đóng</option></select></div>)}</div></ContentPage>; }
function AdminWorkspace({ initialTab = 'overview' }: { initialTab?: string }) {
  const normalizedTab = initialTab === 'dashboard' ? 'overview' : initialTab;
  const [tab, setTab] = useState(normalizedTab);
  useEffect(() => { setTab(initialTab === 'dashboard' ? 'overview' : initialTab); }, [initialTab]);
  const [stats, setStats] = useState({ products: 0, leads: 0, newLeads: 0, posts: 0 });
  const [quotes, setQuotes] = useState<Array<{ id: number; name: string; email: string; phone?: string; message: string; status: string; internal_note?: string; product_id?: string; product_name?: string }>>([]);
  const [users, setUsers] = useState<Array<{ id: number; name: string; email: string; role: string }>>([]);
  const [logs, setLogs] = useState<Array<{ id: number; user_name: string; action: string; resource: string; created_at: string }>>([]);
  const [adminProducts, setAdminProducts] = useState<Array<{ id: string; name: string; category: string; published: number }>>([]);
  const [categories, setCategories] = useState<Array<{ id: number; name: string; slug: string }>>([]);
  const [posts, setPosts] = useState<Array<{ id: number; title: string; type: string; status: string }>>([]);
  const [pages, setPages] = useState<Array<{ id: number; title: string; slug: string; status: string }>>([]);
  const [notice, setNotice] = useState('');
  const [error, setError] = useState('');
  const refresh = async () => { try { const [statsData, quoteData, userData, logData, productData, categoryData, postData, pageData] = await Promise.all([api('/admin/stats'), api('/admin/quotes'), api('/admin/users'), api('/admin/audit-logs'), api('/admin/products'), api('/admin/categories'), api('/admin/posts'), api('/admin/pages')]); setStats(statsData.stats); setQuotes(quoteData.quotes); setUsers(userData.users); setLogs(logData.logs); setAdminProducts(productData.products); setCategories(categoryData.categories); setPosts(postData.posts); setPages(pageData.pages); } catch (e) { setError((e as Error).message); } };
  useEffect(() => { refresh(); }, []);
  useEffect(() => { if (tab !== 'products' || !categories.length) return; const input = document.querySelector<HTMLInputElement>('.admin-product-form input[name="category"]'); if (!input || input.dataset.categoryPicker === 'true') return; const select = document.createElement('select'); select.name = 'category'; select.required = true; select.dataset.categoryPicker = 'true'; select.innerHTML = '<option value="">Chọn danh mục</option>'; categories.forEach(item => { const option = document.createElement('option'); option.value = item.name; option.textContent = item.name; select.appendChild(option); }); input.replaceWith(select); }, [tab, categories]);
  useEffect(() => { if (tab !== 'products') return; const form = document.querySelector<HTMLFormElement>('.admin-product-form'); if (!form || form.dataset.metadataFields === 'true') return; form.dataset.metadataFields = 'true'; const fields = [{ name: 'sku', placeholder: 'Mã SKU/model' }, { name: 'brand', placeholder: 'Hãng/thương hiệu' }, { name: 'videoUrl', placeholder: 'YouTube URL (không bắt buộc)' }, { name: 'badges', placeholder: 'Nhãn, phân cách bằng dấu phẩy' }, { name: 'gallery', placeholder: 'Gallery URL, mỗi dòng một ảnh' }, { name: 'documents', placeholder: 'Tài liệu JSON: [{"name":"Brochure","url":"/media/file.pdf"}]' }, { name: 'specs', placeholder: 'Specs JSON: [{"model":"QD2516","values":{"Vùng cắt":"2500 x 1600 mm"}}]' }]; const anchor = form.querySelector('input[name="image"]'); fields.reverse().forEach(field => { const element = field.name === 'gallery' || field.name === 'documents' || field.name === 'specs' ? document.createElement('textarea') : document.createElement('input'); element.name = field.name; element.placeholder = field.placeholder; if (element instanceof HTMLTextAreaElement) element.rows = 3; anchor?.after(element); }); }, [tab]);
  const updateQuote = async (id: number, status: string, internalNote = '') => { await api(`/admin/quotes/${id}`, { method: 'PATCH', body: JSON.stringify({ status, internalNote }) }); setNotice('Đã cập nhật lead.'); refresh(); };
  const createProduct = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const categoryName = String(form.get('category') || ''); const selectedCategory = categories.find(item => item.name === categoryName); const parseJson = (name: string, fallback: unknown[]) => { try { const value = JSON.parse(String(form.get(name) || '')); return Array.isArray(value) ? value : fallback; } catch { return fallback; } }; try { await api('/admin/products', { method: 'POST', body: JSON.stringify({ id: form.get('id'), name: form.get('name'), slug: form.get('slug'), category: selectedCategory?.name || categoryName, categoryId: selectedCategory?.id || null, sku: form.get('sku'), brand: form.get('brand'), image: form.get('image'), gallery: String(form.get('gallery') || '').split('\n').filter(Boolean), specs: parseJson('specs', []), documents: parseJson('documents', []), badges: String(form.get('badges') || '').split(',').map(value => value.trim()).filter(Boolean), videoUrl: form.get('videoUrl'), description: form.get('description'), featured: form.get('featured') === 'on', bestseller: form.get('bestseller') === 'on' }) }); setNotice('Đã tạo sản phẩm trong danh mục.'); event.currentTarget.reset(); refresh(); } catch (e) { setError((e as Error).message); } };
  const submitCms = async (event: React.FormEvent<HTMLFormElement>, endpoint: string, message: string) => { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = Object.fromEntries(form.entries()); try { await api(endpoint, { method: 'POST', body: JSON.stringify(payload) }); setNotice(message); event.currentTarget.reset(); refresh(); } catch (e) { setError((e as Error).message); } };
  return <ContentPage title="Trung tâm vận hành" kicker="ADMIN"><div className="admin-shell"><aside className="admin-nav"><b>Quản trị nội dung</b>{[['overview','Tổng quan'],['quotes','Leads báo giá'],['products','Sản phẩm'],['users','Người dùng'],['logs','Nhật ký hoạt động']].map(([key, label]) => <button className={tab === key ? 'active' : ''} onClick={() => setTab(key)} key={key}>{label}</button>)}</aside><section className="admin-content">{notice && <div className="admin-notice">{notice}</div>}{error && <div className="form-error">{error}</div>}{tab === 'overview' && <><div className="admin-stat-grid"><div><span>Sản phẩm đang hiển thị</span><b>{stats.products}</b></div><div><span>Tổng lead</span><b>{stats.leads}</b></div><div><span>Lead mới</span><b>{stats.newLeads}</b></div><div><span>Bài viết đã đăng</span><b>{stats.posts}</b></div></div><div className="admin-card"><h2>Việc cần xử lý</h2><p>{stats.newLeads > 0 ? `Bạn có ${stats.newLeads} yêu cầu báo giá mới cần liên hệ.` : 'Không có lead mới cần xử lý.'}</p><button className="btn primary" onClick={() => setTab('quotes')}>Mở hộp thư lead <ArrowRight size={16}/></button></div></>}{tab === 'quotes' && <div className="admin-card"><div className="admin-title"><h2>Hộp thư yêu cầu báo giá</h2><button onClick={refresh}>Làm mới</button></div>{quotes.length === 0 ? <div className="empty-state">Chưa có yêu cầu nào.</div> : quotes.map(quote => <div className="lead-row" key={quote.id}><div><b>{quote.name}</b><span>{quote.email} {quote.phone && `• ${quote.phone}`}</span><p>{quote.message}</p>{quote.product_name && <small>Nguồn sản phẩm: {quote.product_name} ({quote.product_id})</small>}{quote.internal_note && <small>Ghi chú: {quote.internal_note}</small>}</div><div className="lead-actions"><select value={quote.status} onChange={e => updateQuote(quote.id, e.target.value)}><option value="new">Mới</option><option value="contacted">Đang tư vấn</option><option value="quoted">Đã báo giá</option><option value="won">Đã chốt</option><option value="lost">Không tiềm năng</option><option value="closed">Đã đóng</option></select><button onClick={() => { const note = window.prompt('Ghi chú nội bộ', quote.internal_note || '') || ''; updateQuote(quote.id, quote.status, note); }}>Ghi chú</button></div></div>)}</div>}{tab === 'products' && <div className="admin-card"><h2>Thêm sản phẩm</h2><form className="admin-product-form" onSubmit={createProduct}><input name="id" required placeholder="Mã định danh: dao-emma"/><input name="name" required placeholder="Tên sản phẩm"/><input name="slug" required placeholder="URL slug"/><input name="category" required placeholder="Danh mục"/><input name="image" required placeholder="URL ảnh đại diện"/><textarea name="description" required placeholder="Mô tả sản phẩm"/><label><input type="checkbox" name="featured"/> Nổi bật</label><label><input type="checkbox" name="bestseller"/> Bán chạy</label><button className="btn primary">Lưu sản phẩm <ArrowRight size={16}/></button></form><h2 className="admin-subtitle">Danh sách sản phẩm</h2>{adminProducts.map(product => <div className="product-admin-row" key={product.id}><div><b>{product.name}</b><span>{product.category} • {product.published ? 'Đang hiển thị' : 'Đã ẩn'}</span></div>{product.published ? <button onClick={async () => { await api(`/admin/products/${product.id}`, { method: 'DELETE' }); setNotice('Đã ẩn sản phẩm.'); refresh(); }}>Ẩn sản phẩm</button> : <span>Đã ẩn</span>}</div>)}</div>}{tab === 'users' && <div className="admin-card"><h2>Người dùng và phân quyền</h2>{users.map(account => <div className="user-row" key={account.id}><div><b>{account.name}</b><span>{account.email}</span></div><select value={account.role} onChange={async e => { await api(`/admin/users/${account.id}/role`, { method: 'PATCH', body: JSON.stringify({ role: e.target.value }) }); setNotice('Đã cập nhật role.'); refresh(); }}><option value="user">User</option><option value="sales">Sales</option><option value="editor">Editor</option><option value="admin">Admin</option></select></div>)}</div>}{tab === 'logs' && <div className="admin-card"><h2>Nhật ký hoạt động</h2>{logs.length === 0 ? <div className="empty-state">Chưa có hoạt động admin được ghi nhận.</div> : logs.map(log => <div className="log-row" key={log.id}><b>{log.user_name}</b><span>{log.action} • {log.resource}</span><time>{log.created_at}</time></div>)}</div>}</section></div></ContentPage>;
}
function App() {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('Tất cả'); const [products, setProducts] = useState<Product[]>(seedProducts); const [cart, setCart] = useState<string[]>(() => JSON.parse(localStorage.getItem('ct_cart') || '[]')); const [menu, setMenu] = useState(false); const [sent, setSent] = useState(false); const [hash, setHash] = useState(window.location.hash || '#/');
  useEffect(() => { const syncRoute = () => setHash(window.location.hash || '#/'); window.addEventListener('hashchange', syncRoute); return () => window.removeEventListener('hashchange', syncRoute); }, []);
  useEffect(() => { window.scrollTo({ top: 0, left: 0, behavior: 'auto' }); }, [hash]);
  const refreshProducts = async () => { try { const data = await api('/products'); setProducts(data.products); } catch { /* Keep current catalog when API is temporarily unavailable. */ } };
  useEffect(() => { refreshProducts(); }, []);
  useEffect(() => { const refreshOnRoute = () => { const current = window.location.hash; if (current.includes('#/san-pham') || current.includes('#/danh-muc')) refreshProducts(); }; window.addEventListener('hashchange', refreshOnRoute); window.addEventListener('focus', refreshOnRoute); const onProductChanged = () => refreshProducts(); window.addEventListener('products-changed', onProductChanged); return () => { window.removeEventListener('hashchange', refreshOnRoute); window.removeEventListener('focus', refreshOnRoute); window.removeEventListener('products-changed', onProductChanged); }; }, []);
  useEffect(() => { localStorage.setItem('ct_cart', JSON.stringify(cart)); }, [cart]);
  const selected = products.find(p => hash.includes(p.slug)); const categorySlug = hash.split('/')[2]; const routeCategory = categorySlug === 'may-cat-kts' ? 'Máy cắt KTS' : categorySlug === 'luoi-dao' ? 'Lưỡi dao' : categorySlug === 'tham-ni' ? 'Thảm nỉ' : categorySlug === 'dau-dao-may-cat-kts' ? 'Đầu dao máy cắt KTS' : category; const filtered = useMemo(() => products.filter(p => (routeCategory === 'Tất cả' || p.category === routeCategory) && p.name.toLowerCase().includes(query.toLowerCase())), [routeCategory, query, products]);
  const route = hash.replace(/^#\//, '').split('?')[0].split('/')[0];
  const [user, setUser] = useState<User | null>(null); const [authChecked, setAuthChecked] = useState(false); const [settings, setSettings] = useState<Record<string,string>>({}); const [sliders, setSliders] = useState<any[]>([]);
  useEffect(() => { api('/auth/me').then(data => setUser(data.user)).catch(() => undefined).finally(() => setAuthChecked(true)); const refreshSettings = () => api('/settings').then(data => setSettings(data.settings)).catch(() => undefined); refreshSettings(); api('/sliders').then(data => setSliders(data.sliders)).catch(() => undefined); window.addEventListener('settings-changed', refreshSettings); window.addEventListener('focus', refreshSettings); return () => { window.removeEventListener('settings-changed', refreshSettings); window.removeEventListener('focus', refreshSettings); }; }, []);
  useEffect(() => { const submitQuote = async (event: Event) => { const form = event.target as HTMLFormElement; if (!form.matches('.quick-quote')) return; event.preventDefault(); event.stopImmediatePropagation(); let status = form.querySelector<HTMLElement>('.quick-quote-status'); if (!status) { status = document.createElement('p'); status.className = 'quick-quote-status'; form.appendChild(status); } status.className = 'quick-quote-status pending'; status.textContent = 'Đang gửi yêu cầu...'; const data = new FormData(form); try { const slug = window.location.hash.split('/')[2]; const productData = await api('/products'); const product = productData.products.find((item: Product) => item.slug === slug); await api('/quotes', { method: 'POST', body: JSON.stringify({ name: data.get('name'), phone: data.get('phone'), email: data.get('email'), message: data.get('message'), items: product ? [{ productId: product.id, quantity: 1 }] : [] }) }); status.className = 'quick-quote-status success'; status.textContent = 'Đã gửi yêu cầu. Chúng tôi sẽ liên hệ sớm.'; form.reset(); } catch (error) { status.className = 'quick-quote-status error'; status.textContent = (error as Error).message || 'Gửi yêu cầu thất bại.'; } }; document.addEventListener('submit', submitQuote, true); return () => document.removeEventListener('submit', submitQuote, true); }, []);
  useEffect(() => { if (!authChecked) return; if (user?.role === 'admin' && (route === 'admin-login' || route === 'dang-nhap')) window.location.hash = '#/admin?tab=dashboard'; }, [authChecked, user, route]);
  if (route === 'du-an' && hash.split('/').length > 2) return <div><Header onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><ProjectDetailPage slug={hash.split('/')[2]}/><SharedFooter settings={settings}/></div>;
  if (route === 'du-an') return <div><Header onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><ProjectsPage/><SharedFooter settings={settings}/></div>;
  if (route === 'lien-he') return <div><Header onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><ContactPage settings={settings}/><SharedFooter settings={settings}/></div>;
  if (route === 'tin-tuc' && hash.split('/').length > 2) return <div><Header onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><NewsDetailPage slug={hash.split('/')[2]}/><SharedFooter settings={settings}/></div>;
  if (route === 'tin-tuc') return <div><Header onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><NewsPage/><SharedFooter settings={settings}/></div>;
  if (route === 'gioi-thieu') return <div><Header onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><CmsPublicPage slug="gioi-thieu" fallbackTitle="Kinh nghiệm tạo nên khác biệt." fallbackKicker="VỀ CHÍNH THỰC"/><SharedFooter settings={settings}/></div>;
  if (route === 'dang-nhap') return <div><Header cart={cart.length} onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><AuthPage onLogin={setUser}/></div>;
  if (route === 'admin-login') return <div><Header cart={cart.length} onMenu={() => setMenu(true)} onSearch={setQuery}/><AuthPage adminOnly onLogin={setUser}/></div>;
  if (selected && isProductDetailRoute(route, hash)) return <div><Header cart={cart.length} onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><ProductDetailPage product={selected} onAdd={id => setCart(items => [...items, id])}/><SharedFooter settings={settings}/></div>;
  if (route === 'san-pham' || route === 'danh-muc') return <div><Header cart={cart.length} onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/><ProductCatalogPage products={products} query={query} setQuery={setQuery} category={category} setCategory={setCategory} categorySlug={route === 'danh-muc' ? hash.split('/')[2] : undefined}/><SharedFooter settings={settings}/></div>;
  if (route === 'admin') { const adminTab = new URLSearchParams(hash.split('?')[1] || '').get('tab') || 'dashboard'; if (!authChecked) return <div className="admin-loading">Đang xác thực khu vực quản trị...</div>; return user?.role === 'admin' ? <AdminErrorBoundary><AdminFrameSafe user={user} active={adminTab} settings={settings}>{adminTab === 'content' ? <CmsAdminPage api={api}/> : adminTab === 'products' ? <ProductAdminV2 api={api} onProductsChanged={() => window.dispatchEvent(new Event('products-changed'))}/> : <AdminWorkspace initialTab={adminTab}/>}</AdminFrameSafe></AdminErrorBoundary> : <div className="admin-denied"><h1>Không có quyền truy cập</h1><a href="#/admin-login">Đăng nhập quản trị</a></div>; }
  if (route === 'admin-cms') { window.location.hash = '#/admin?tab=content'; return null; }
  if (!route) return <div><Header onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/>{menu && <div className="mobile-menu"><button className="close" onClick={() => setMenu(false)} aria-label="Đóng menu"><X/></button>{['Trang chủ','Giới thiệu','Sản phẩm','Tin tức','Dự án','Liên hệ'].map(item => <a href={item === 'Trang chủ' ? '#/' : `#/${item.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMenu(false)} key={item}>{item}</a>)}</div>}<HomePage products={products} settings={settings} sliders={sliders}/><SharedFooter settings={settings}/></div>;
  const add = (id: string) => setCart(c => [...c, id]);
  return <div><Header cart={cart.length} onMenu={() => setMenu(true)} onSearch={setQuery} user={user} settings={settings}/>{menu && <div className="mobile-menu"><button className="close" onClick={() => setMenu(false)} aria-label="Đóng menu"><X/></button>{['Trang chủ','Giới thiệu','Sản phẩm','Tin tức','Dự án','Liên hệ'].map(x => <a href={x === 'Trang chủ' ? '#/' : `#/${x.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMenu(false)} key={x}>{x}</a>)}</div>}
    {selected ? <main><section className="detail container"><div className="detail-image"><img src={selected.image} alt={selected.name}/></div><div className="detail-copy"><span className="eyebrow">{selected.category}</span><h1>{selected.name}</h1><p className="price">Giá liên hệ</p><p>{selected.description}</p><div className="specs"><div><b>01</b><span>Hỗ trợ kỹ thuật<br/>chuyên sâu</span></div><div><b>02</b><span>Phụ kiện<br/>tương thích</span></div><div><b>03</b><span>Giao hàng<br/>toàn quốc</span></div></div><button className="btn primary" onClick={() => add(selected.id)}>Thêm vào yêu cầu báo giá <ArrowRight size={17}/></button></div></section></main> : route === 'gioi-thieu' ? <ContentPage title="Kinh nghiệm tạo nên khác biệt." kicker="VỀ CHÍNH THỰC"><h2>Đơn vị đồng hành kỹ thuật cho sản xuất Việt.</h2><p>CHÍNH THỰC là đơn vị chuyên cung cấp máy cắt kỹ thuật số, lưỡi dao và phụ kiện CNC. Với hơn 12 năm kinh nghiệm, đội ngũ kỹ thuật am hiểu thiết bị giúp khách hàng chọn đúng giải pháp và vận hành hiệu quả.</p></ContentPage> : route === 'tin-tuc' ? <ContentPage title="Kiến thức ngành" kicker="TIN TỨC"><div className="article-list"><article><span className="eyebrow">ỨNG DỤNG</span><h2>Sản xuất và gia công tùy chỉnh với máy cắt kỹ thuật số</h2><p>Khám phá cách tối ưu quy trình cắt, giảm hao phí vật liệu và tăng độ chính xác.</p></article><article><span className="eyebrow">VẬT TƯ</span><h2>Lưỡi dao công nghiệp phục vụ ngành thực phẩm và bao bì</h2><p>Những lưu ý khi lựa chọn lưỡi dao phù hợp với từng vật liệu.</p></article></div></ContentPage> : route === 'du-an-old' ? <ContentPage title="Dự án đã thực hiện" kicker="DỰ ÁN"><div className="empty-state">Dữ liệu dự án đang được cập nhật.</div></ContentPage> : route === 'lien-he' ? <ContentPage title="Trao đổi với chuyên gia" kicker="LIÊN HỆ"><div className="contact-grid"><div><h2>Chúng tôi sẵn sàng tư vấn.</h2><p>Hotline: <b>0916 412 896</b></p><p>Email: chinhthucmaycnc@gmail.com</p><p>Bình Dương, Việt Nam</p></div><form onSubmit={e => { e.preventDefault(); setSent(true); }}><label>Họ tên<input required placeholder="Nhập họ tên"/></label><label>Email<input required type="email" placeholder="you@company.com"/></label><label>Nội dung<textarea required placeholder="Bạn cần tư vấn sản phẩm nào?"/></label><button className="btn primary" type="submit">Gửi yêu cầu <ArrowRight size={17}/></button></form></div></ContentPage> : route === 'gio-hang' ? <ContentPage title="Yêu cầu báo giá" kicker="GIỎ HÀNG"><p>Bạn đã chọn <b>{cart.length}</b> sản phẩm. Chúng tôi sẽ liên hệ để xác nhận cấu hình và báo giá.</p>{cart.length === 0 ? <div className="empty-state">Chưa có sản phẩm nào. <a href="#/san-pham">Xem danh mục sản phẩm</a></div> : <div className="cart-list">{cart.map((id, index) => <div key={`${id}-${index}`}><span>{products.find(p => p.id === id)?.name}</span><button onClick={() => setCart(c => c.filter((_, i) => i !== index))}>Xóa</button></div>)}</div>}</ContentPage> : <main><section className="hero"><div className="hero-content"><span className="eyebrow light">ĐỐI TÁC KỸ THUẬT CỦA BẠN</span><h1>Giải pháp cắt<br/><i>chính xác.</i> Sản xuất<br/>hiệu quả hơn.</h1><p>Máy cắt kỹ thuật số, lưỡi dao và phụ kiện chuyên dụng cho doanh nghiệp Việt.</p><div><a className="btn yellow" href="#/san-pham">Khám phá sản phẩm <ArrowRight size={17}/></a><a className="textlink" href="#/gioi-thieu">Về Chính Thực <ArrowRight size={16}/></a></div></div><div className="hero-image"><img src="https://chinhthucmayktscnc.com/wp-content/uploads/2025/09/banner-1-1400x609.png" alt="Máy cắt kỹ thuật số Chính Thực"/></div>{sliders.length > 1 && <div className="hero-dots" aria-label="Điều hướng slider">{sliders.map((slider, index) => <button type="button" className={index === slideIndex ? 'active' : ''} aria-label={`Chuyển tới slide ${index + 1}`} onClick={() => { setSlideIndex(index); setSlideFailed(false); }} key={slider.id}/>)}</div>}</section>{false && <section className="hero-slider" aria-label="Slider trang chủ">{sliders.map(slider => <a href={slider.link || '#/san-pham'} key={slider.id}><img src={slider.image} alt={slider.title || 'Slider Chính Thực'}/>{slider.title && <span>{slider.title}</span>}</a>)}</section>}<section className="trust"><div><Zap size={22}/><span><b>12+ năm</b><small>Kinh nghiệm ngành máy</small></span></div><div><span className="trustnum">100%</span><span><b>Chính hãng</b><small>Sản phẩm nguồn gốc rõ ràng</small></span></div><div><Phone size={22}/><span><b>0916 412 896</b><small>Tư vấn kỹ thuật tận tâm</small></span></div></section><section className="catalog container" id="san-pham"><div className="section-head"><div><span className="eyebrow">DANH MỤC SẢN PHẨM</span><h2>Thiết bị cho mọi<br/><i>đường cắt.</i></h2></div><p>Từ máy cắt công nghiệp đến phụ kiện chính xác, chúng tôi cung cấp giải pháp đồng bộ để quy trình của bạn vận hành trơn tru.</p></div><div className="filters">{categories.map(c => <button className={category === c ? 'active' : ''} onClick={() => setCategory(c)} key={c}>{c}</button>)}<label className="catalog-search"><Search size={16}/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Tìm nhanh trong danh mục"/></label></div><div className="grid">{filtered.map(p => <ProductCard p={p} key={p.id}/>)}</div></section><section className="cta"><div><span className="eyebrow light">CHƯA BIẾT CHỌN GÌ?</span><h2>Hãy để chúng tôi<br/><i>tư vấn giải pháp.</i></h2></div><a className="btn yellow" href="#/lien-he">Trao đổi với chuyên gia <ArrowRight size={17}/></a></section></main>}
     <SharedFooter settings={settings}/>{sent && <div className="toast">Yêu cầu đã được ghi nhận. Chúng tôi sẽ liên hệ sớm.</div>}</div>;
}
createRoot(document.getElementById('root')!).render(<StrictMode><App/></StrictMode>);
